// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetShipping The store's shipping settings and zones
	// (GET /v1/stores/{store_id}/shipping)
	GetShipping(ctx context.Context, request GetShippingRequestObject) (GetShippingResponseObject, error)
	// ListCarrierConnections The carriers available and the store's connections
	// (GET /v1/stores/{store_id}/shipping/carriers)
	ListCarrierConnections(ctx context.Context, request ListCarrierConnectionsRequestObject) (ListCarrierConnectionsResponseObject, error)
	// ConnectCarrier Connect the store's account at a carrier
	// (POST /v1/stores/{store_id}/shipping/carriers)
	ConnectCarrier(ctx context.Context, request ConnectCarrierRequestObject) (ConnectCarrierResponseObject, error)
	// DisconnectCarrier Disconnect a carrier account
	// (DELETE /v1/stores/{store_id}/shipping/carriers/{connection_id})
	DisconnectCarrier(ctx context.Context, request DisconnectCarrierRequestObject) (DisconnectCarrierResponseObject, error)
	// GetCODReport Cash-on-delivery reconciliation
	// (GET /v1/stores/{store_id}/shipping/cod)
	GetCODReport(ctx context.Context, request GetCODReportRequestObject) (GetCODReportResponseObject, error)
	// ListHeldCOD Delivered parcels whose cash the carrier still holds
	// (GET /v1/stores/{store_id}/shipping/cod/held)
	ListHeldCOD(ctx context.Context, request ListHeldCODRequestObject) (ListHeldCODResponseObject, error)
	// ImportCODStatement Import a carrier's settlement statement (CSV)
	// (POST /v1/stores/{store_id}/shipping/cod/statements)
	ImportCODStatement(ctx context.Context, request ImportCODStatementRequestObject) (ImportCODStatementResponseObject, error)
	// QuoteShipping What delivering an order would cost
	// (POST /v1/stores/{store_id}/shipping/quote)
	QuoteShipping(ctx context.Context, request QuoteShippingRequestObject) (QuoteShippingResponseObject, error)
	// SaveShippingSettings Save the store-wide COD fee and free-shipping threshold
	// (PUT /v1/stores/{store_id}/shipping/settings)
	SaveShippingSettings(ctx context.Context, request SaveShippingSettingsRequestObject) (SaveShippingSettingsResponseObject, error)
	// ListShipments The store's shipments, newest first
	// (GET /v1/stores/{store_id}/shipping/shipments)
	ListShipments(ctx context.Context, request ListShipmentsRequestObject) (ListShipmentsResponseObject, error)
	// CreateShipments Hand orders to a connected carrier
	// (POST /v1/stores/{store_id}/shipping/shipments)
	CreateShipments(ctx context.Context, request CreateShipmentsRequestObject) (CreateShipmentsResponseObject, error)
	// GetShipment A shipment with its timeline
	// (GET /v1/stores/{store_id}/shipping/shipments/{shipment_id})
	GetShipment(ctx context.Context, request GetShipmentRequestObject) (GetShipmentResponseObject, error)
	// CancelShipment Cancel a shipment
	// (POST /v1/stores/{store_id}/shipping/shipments/{shipment_id}/cancel)
	CancelShipment(ctx context.Context, request CancelShipmentRequestObject) (CancelShipmentResponseObject, error)
	// GetShipmentLabel The shipment's label (airway bill)
	// (GET /v1/stores/{store_id}/shipping/shipments/{shipment_id}/label)
	GetShipmentLabel(ctx context.Context, request GetShipmentLabelRequestObject) (GetShipmentLabelResponseObject, error)
	// CreateShippingZone Add a delivery zone
	// (POST /v1/stores/{store_id}/shipping/zones)
	CreateShippingZone(ctx context.Context, request CreateShippingZoneRequestObject) (CreateShippingZoneResponseObject, error)
	// DeleteShippingZone Delete a zone
	// (DELETE /v1/stores/{store_id}/shipping/zones/{zone_id})
	DeleteShippingZone(ctx context.Context, request DeleteShippingZoneRequestObject) (DeleteShippingZoneResponseObject, error)
	// UpdateShippingZone Replace a zone (name, rates, governorates, cities)
	// (PUT /v1/stores/{store_id}/shipping/zones/{zone_id})
	UpdateShippingZone(ctx context.Context, request UpdateShippingZoneRequestObject) (UpdateShippingZoneResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

